head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDODS60201";
scwin.divConfirmMsg = null;
scwin.isu_nm = null;
scwin.list_dd = null;
scwin.per1stk_cap = null;
scwin.list_shrs = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — kclicUsrTpId, ipt_isurCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "input_154", fn: function(){ return ((dma_pageContext.get("kclicUsrTpId") ?? "") === 'LIST_CORP_DISCLS'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await alertE("저장되었습니다.");
        await alertE("수정되었습니다.");
        await alertE("삭제되었습니다.");
        await alertE("오류가 발생하였습니다.\n시스템 담당자에게 문의하시기 바랍니다.");

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods60201.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.divConfirmMsg = $c.util.getComponent('divConfirmMsg');
        scwin.isu_nm = $c.util.getComponent('ipt_isuNm_2');
        scwin.list_dd = $c.util.getComponent('listDd');
        scwin.per1stk_cap = $c.util.getComponent('ipt_per1stkCap_2');
        scwin.list_shrs = $c.util.getComponent('ipt_listShrs_2');
        scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods60201.onpageload' });
    }
};

