 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.stkStatTable_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_stokOccrStat');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_stokOccrStat */ return; }
