///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name numberFormat
 * @description number Format 처리
 * @param {*} numstr numstr
 * @param {*} ret ret
 * @returns {void}
 * @hidden N
 */
scwin.numberFormat = function (numstr, ret) {
    if (numstr != null && numstr !== '') {
        numstr = scwin.setComma(scwin.delComma(numstr));
        if (ret) {
            ret.value = numstr;
        }
        return numstr;
    }
};

/**
 * @method
 * @name setComma
 * @description set Comma 처리
 * @param {*} numstr numstr
 * @returns {void}
 * @hidden N
 */
scwin.setComma = function (numstr) {
    numstr = String(numstr);
    const re0 = /^(-?\d+)(\d{3})($|\..*$)/;
    if (re0.test(numstr)) {
        return numstr.replace(re0, function(str, p1, p2, p3) {
                return scwin.setComma(p1) + ',' + p2 + p3;
        });
    } else {
        return numstr;
    }
};

/**
 * @method
 * @name delComma
 * @description del Comma 처리
 * @param {*} numstr numstr
 * @returns {void}
 * @hidden N
 */
scwin.delComma = function (numstr) {
    numstr = String(numstr);
    if (numstr === '') {
        return '';
    } else {
        if (numstr === '0-') {
            return '';
        }
    }
    numstr = numstr.replace(/[^\d\.-]/g, '');
    numstr = String(numstr.match(/^-?\d*\.?\d*/));
    numstr = numstr.replace(/^(-?)(\d*)(.*)/, function(str, p1, p2, p3) {
            p2 = (p2 > 0) ? String(p2.match(/[1-9]\d*$/)) : '0';
            return p1 + p2 + p3;
    });
    return numstr;
};

/**
 * @method
 * @name addRow
 * @description add Row 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addRow = async function () {
    if (scwin.addRow.style.display === "block") {
        await alertE("입력중인 데이터를 저장한 후에 추가 입력이 가능합니다.");
        return;
    } else {
        $('#removeCheckId').removeClass("end");
        $('#removeCheckIdNoData').remove();
        $('#removeCheckIdNoData').removeClass("end");
        scwin.addRow.setStyle("display", "block");
    }
};

/**
 * @method
 * @name goSave
 * @description go Save 처리
 * @param {String} ipt_isurCd ipt_isurCd
 * @param {*} ipt_seqNum ipt_seqNum
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goSave = async function (ipt_isurCd, ipt_seqNum) {
    if ($('#ipt_isuNm_2', $('#stkStatForm')).val() === "") {
        await alertE("종목명을 입력하십시오.");
        scwin.isu_nm.focus();
        return;
    }
    if ($('#ipt_listDd_2', $('#stkStatForm')).val() === "") {
        await alertE("신규상장일을 선택하십시오.");
        scwin.list_dd.focus();
        return;
    }
    if ($('#ipt_per1stkCap_2', $('#stkStatForm')).val() === "") {
        await alertE("1주당액면가를 입력하십시오.");
        scwin.per1stk_cap.focus();
        return;
    }
    if ($('#ipt_listShrs_2', $('#stkStatForm')).val() === "") {
        await alertE("상장주식수를 입력하십시오.");
        scwin.list_shrs.focus();
        return;
    }
    $c.util.getComponent('ipt_SCREN_PROCES_TP_CD').setValue("02");
    $c.util.getComponent('ipt_crudFlag').setValue("C");
    $c.util.getComponent('ipt_isurCd').setValue(ipt_isurCd);
    $c.util.getComponent('ipt_isuNm').setValue(($c.util.getComponent("ipt_isuNm_2").getValue() || ''));
    $c.util.getComponent('ipt_listDd').setValue(($c.util.getComponent("ipt_listDd_2").getValue() || ''));
    $c.util.getComponent('ipt_parTpCd').setValue(($c.util.getComponent("slc_parTpCd").getValue() || ''));
    $c.util.getComponent("ipt_per1stkCap").setValue($c.num.unFormatNumber($c.util.getComponent('ipt_per1stkCap_2').getValue()));
    $c.util.getComponent("ipt_listShrs").setValue($c.num.unFormatNumber($c.util.getComponent('ipt_listShrs_2').getValue()));
    scwin.confirmE("저장하시겠습니까?");
};

/**
 * @method
 * @name goAdj
 * @description go Adj 처리
 * @param {String} ipt_isurCd ipt_isurCd
 * @param {*} ipt_seqNum ipt_seqNum
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goAdj = async function (ipt_isurCd, ipt_seqNum) {
    if ($('#ipt_isuNm_2' + ipt_seqNum, $('#stkStatForm')).val() === "") {
        await alertE("종목명을 입력하십시오.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if ($('#ipt_listDd_2' + ipt_seqNum, $('#stkStatForm')).val() === "") {
        await alertE("신규상장일을 선택하십시오.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if ($('#ipt_per1stkCap_2' + ipt_seqNum, $('#stkStatForm')).val() === "") {
        await alertE("1주당액면가를 입력하십시오.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if ($('#ipt_listShrs_2' + ipt_seqNum, $('#stkStatForm')).val() === "") {
        await alertE("상장주식수를 입력하십시오.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    $c.util.getComponent('ipt_SCREN_PROCES_TP_CD').setValue("03");
    $c.util.getComponent('ipt_crudFlag').setValue("U");
    $c.util.getComponent('ipt_isurCd').setValue(ipt_isurCd);
    $c.util.getComponent('ipt_seqNum').setValue(ipt_seqNum);
    $c.util.getComponent('ipt_isuNm').setValue($("#ipt_isuNm_2" + ipt_seqNum).val());
    $c.util.getComponent('ipt_listDd').setValue($("#ipt_listDd_2" + ipt_seqNum).val());
    $c.util.getComponent('ipt_parTpCd').setValue($("#slc_parTpCd" + ipt_seqNum).val());
    $c.util.getComponent("ipt_per1stkCap").setValue($c.num.unFormatNumber($("#ipt_per1stkCap_2" + ipt_seqNum).val()));
    $c.util.getComponent("ipt_listShrs").setValue($c.num.unFormatNumber($("#ipt_listShrs_2" + ipt_seqNum).val()));
    scwin.confirmE("수정하시겠습니까?");
};

